{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "실행 계획에서 확인한 병목과 개선 방법을 연결해 판단할 수 있는지 평가한다. 신고 목록 조회 쿼리에서 인덱스 추가와 조인 정리를 선택한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 운영 화면의 신고 목록 조회 쿼리 실행 계획을 보고 신고 테이블과 판매글 테이블을 매번 전체 조인하는 것을 확인했다.",
          "task": "조회에 3.2초가 걸리던 쿼리에 조회 조건에 맞는 인덱스를 추가하고 조인 순서를 정리했다.",
          "action": "실행 계획과 조회 조건에서 어떤 정보를 근거로 인덱스 추가와 조인 정리를 선택했는지 설명한다.",
          "result": "선택한 수정이 확인한 병목을 줄이는 데 적합하다고 판단한 이유를 설명한다."
        },
        "expectedEvidence": [
          "인덱스 추가와 조인 정리를 선택한 판단 근거",
          "선택을 뒷받침한 실행 계획과 조회 조건의 구체적인 정보",
          "확인한 병목과 선택한 수정 사이의 연결"
        ]
      },
      "question": "포켓마켓의 신고 목록 조회 쿼리 실행 계획을 보셨을 때, 인덱스 추가와 조인 정리를 택한 근거는 무엇이었나요?",
      "answerTip": "핵심부터 말하고 필요한 설명을 덧붙여 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획과 조회 조건의 구체적인 정보를 들어 인덱스 추가와 조인 정리를 선택한 근거를 설명한다.",
            "선택한 수정이 불필요한 조회나 조인 부담을 줄이는 이유를 확인한 병목과 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "인덱스 추가와 조인 정리의 선택 이유를 설명하지만 실행 계획이나 조회 조건에 관한 근거가 일반적이다.",
            "수정과 병목의 연결은 타당하지만 두 수정 중 일부의 선택 근거가 충분하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "선택 이유 없이 인덱스를 추가하고 조인을 정리했다는 사실이나 응답 시간만 반복한다.",
            "실행 계획에서 확인한 병목과 무관한 일반론을 말하거나 선택한 수정의 효과를 잘못 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류를 추적한 결과를 같은 장애의 재발 방지 판단으로 연결할 수 있는지 평가한다. 스케줄러 오류를 수정한 것과 별개로 배포 체크리스트에 스케줄러 항목을 넣은 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 알림 중복 발송 문의를 받고 로그를 시간순으로 살펴 스케줄러가 서버 두 대에서 동시에 실행되는 것을 찾았다.",
          "task": "잠금 키를 두는 방식으로 오류를 고쳤고 이후 배포 체크리스트에 스케줄러 항목을 넣었다.",
          "action": "배포 체크리스트에 스케줄러 항목을 넣어야 한다고 판단한 근거를 설명한다.",
          "result": "추가한 항목이 같은 장애의 재발 방지에 도움이 된다고 판단한 이유를 설명하며 실제 재발 여부나 이후 성과는 요구하지 않는다."
        },
        "expectedEvidence": [
          "배포 체크리스트에 스케줄러 항목을 넣은 판단 근거",
          "항목 추가가 필요하다고 판단할 당시의 오류 관련 정보",
          "스케줄러 항목 추가와 같은 장애의 재발 방지 사이의 연결"
        ]
      },
      "question": "포켓마켓에서 로그로 스케줄러의 두 서버 동시 실행을 찾으셨을 때, 배포 체크리스트에 스케줄러 항목을 넣은 근거는 무엇이었나요?",
      "answerTip": "한 사례에 집중해 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "확인한 오류의 특성을 근거로 배포 체크리스트에 스케줄러 항목을 넣을 필요성을 구체적으로 설명한다.",
            "체크리스트 항목 추가가 같은 장애의 반복 가능성을 줄이는 이유를 당장의 오류 수정과 구별해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "같은 오류를 막기 위해 항목을 넣었다고 설명하지만 당시 정보와 연결한 근거가 일반적이다.",
            "체크리스트 항목의 재발 방지 역할은 타당하게 설명하지만 오류 수정 외에 필요한 이유는 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "항목을 추가한 근거 없이 로그 추적이나 잠금 키 수정 사실만 설명한다.",
            "체크리스트 항목 추가와 같은 장애의 재발 방지 사이의 관련성을 설명하지 못하거나 잘못 연결한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "현업·사용자 요청을 구현할 요구사항으로 구체화할 때 포함할 범위를 판단할 수 있는지 확인한다. 개발 담당 팀원과 범위를 조정한 근거가 요청의 목적과 구현 범위를 타당하게 연결하는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳을 인터뷰하고 요구사항 정의서를 작성했다.",
          "task": "기획 담당으로 개발 담당 팀원과 범위를 조정했다.",
          "action": "개발 담당 팀원과 범위를 조정한 근거를 당시 요청의 목적과 구현 조건에 연결해 설명한다.",
          "result": "설명한 근거가 해당 범위를 선택하는 데 타당했던 이유를 밝힌다. 이후 구현 성과는 요구하지 않는다."
        },
        "expectedEvidence": [
          "개발 담당 팀원과 범위를 조정한 구체적인 판단 근거",
          "범위 판단을 뒷받침한 요청의 목적이나 당시 구현 조건"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 요구사항 정의서를 작성하셨을 때, 개발 담당 팀원과 범위를 조정한 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "어떤 요구를 범위에 포함하거나 제외할지 결정한 근거를 구체적으로 설명한다.",
            "제시한 근거가 요청의 목적이나 당시 구현 조건과 연결되어 범위 조정의 타당성을 보여 준다."
          ]
        },
        "acceptable": {
          "criteria": [
            "범위를 조정한 근거를 제시하지만 중요도나 구현 가능성 같은 일반적인 설명에 머문다.",
            "근거와 범위 선택의 연결은 드러나지만 이를 뒷받침하는 당시 정보가 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항 정의서를 작성하거나 협의했다는 사실만 말하고 범위를 조정한 근거는 제시하지 못한다.",
            "제시한 설명이 요구사항의 포함·제외 판단과 무관하거나 범위 선택을 뒷받침하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "화면 흐름에서 예외 상황을 판단하고 화면설계에 반영할 수 있는지 확인한다. 정상 흐름과 달리 처리해야 할 상황을 예외로 설계한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 Figma로 화면설계서 28장을 작성했다.",
          "task": "화면설계서에 예약·취소·알림 흐름과 예외 상황을 담았다.",
          "action": "예외 상황을 설계한 근거를 해당 화면 흐름의 조건과 연결해 설명한다.",
          "result": "설명한 근거를 통해 정상 흐름과 다른 처리가 필요한 이유가 드러난다. 구현 이후 성과는 요구하지 않는다."
        },
        "expectedEvidence": [
          "화면설계서에서 예외 상황을 설계한 구체적인 판단 근거",
          "그 판단을 뒷받침한 정상 흐름과 예외 상황의 조건 차이"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨을 때, 예외 상황을 설계한 근거는 무엇이었나요?",
      "answerTip": "떠오르는 경험을 짧은 문장으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "화면 흐름에서 어떤 상황을 예외로 설계했는지 알 수 있도록 판단 근거를 구체적으로 설명한다.",
            "제시한 근거가 정상 흐름과 다른 처리가 필요한 조건에 연결되어 예외 설계의 타당성을 보여 준다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황을 설계한 근거를 제시하지만 사용자 불편 방지 등 일반적인 설명에 머문다.",
            "근거와 예외 설계의 연결은 드러나지만 정상 흐름과 달라지는 조건에 대한 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 포함했다는 사실이나 화면설계 도구만 설명하고 설계 근거는 제시하지 못한다.",
            "제시한 근거가 예외 상황의 판단과 무관하거나 정상 흐름과 다른 처리가 필요한 이유를 뒷받침하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방 용량이 의심스러울 때 그대로 투약하지 않고 멈출 수 있는지 평가한다. 평소 용량과 다른 처방을 투약 중단의 근거로 판단한 이유에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원에서 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어온 경험이다.",
          "task": "지원자는 투약 전에 처방 용량의 이상을 느껴 투약을 멈췄다.",
          "action": "당시 처방 용량을 의심한 정보와 투약을 멈추기로 판단한 근거를 설명한다.",
          "result": "처방의 적절성이 불확실한 상태에서 투약을 진행하지 않은 판단의 타당성을 설명한다."
        },
        "expectedEvidence": [
          "투약을 멈추기로 판단한 구체적인 근거",
          "판단 당시 비교한 처방 용량과 평소 용량의 차이",
          "용량 차이가 있는 상태에서 투약을 진행할 경우 우려한 위험"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 처방 용량이 평소의 두 배였을 때, 투약을 멈추기로 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 경험을 떠올리며 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방 용량과 평소 용량의 차이를 구체적으로 짚어 투약을 멈춘 근거를 설명한다.",
            "용량 차이만으로 오류를 단정하지 않으면서도 적절성이 불확실한 투약의 위험을 중단 판단과 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소보다 높은 용량이어서 투약을 멈췄다고 답하지만 비교한 정보에 대한 설명이 제한적이다.",
            "의심스러운 처방은 그대로 수행하지 않아야 한다고 설명하지만 당시 판단 근거는 일반적인 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 사실이나 이후 입력 오류였다는 결과만 반복하고 당시 판단 근거를 제시하지 못한다.",
            "처방 용량의 의심 여부와 무관한 업무 관행이나 개인적 느낌만으로 중단을 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태와 관련된 정보를 다음 근무자에게 빠짐없이 전달할 수 있는지 평가한다. 진통제 투여 시각과 보행 보조 여부를 인수인계 항목으로 선정한 판단에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동의 낙상 고위험 환자 인수인계 체크리스트 개선 활동에 참여했다.",
          "task": "사고 보고서에서 수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰린다는 점을 확인하고 진통제 투여 시각과 보행 보조 여부를 인수인계 항목에 넣자고 제안했다.",
          "action": "두 정보를 인수인계 항목으로 선정한 근거와 당시 확인한 정보의 연관성을 설명한다.",
          "result": "제시한 근거를 통해 두 항목이 다음 근무자의 환자 상태 파악에 필요한 이유를 설명한다."
        },
